using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.Dtos; using RaceDay.Api.Models; using RaceDay.Api.Services; namespace RaceDay.Api.Controllers; [ApiController,Route("api/events")] public class EventsController(RaceDayDbContext db):ControllerBase { [HttpGet] public async Task<ActionResult<IEnumerable<EventResponse>>> GetAll()=>Ok(await db.Events.AsNoTracking().OrderBy(x=>x.EventDate).Select(x=>new EventResponse(x.EventId,x.OrganiserId,x.EventName,x.Description,x.EventDate,x.Venue,x.City,x.Province,x.EventType,x.Status,x.CreatedAt,x.BannerImageUrl)).ToListAsync()); [HttpGet("{id:int}")] public async Task<ActionResult<EventDetailsResponse>> GetById(int id){var e=await db.Events.AsNoTracking().Include(x=>x.Categories).Include(x=>x.Routes).SingleOrDefaultAsync(x=>x.EventId==id);if(e==null)return NotFound();return Ok(new EventDetailsResponse(new EventResponse(e.EventId,e.OrganiserId,e.EventName,e.Description,e.EventDate,e.Venue,e.City,e.Province,e.EventType,e.Status,e.CreatedAt,e.BannerImageUrl),e.Categories.Select(c=>new CategoryResponse(c.CategoryId,c.EventId,c.CategoryName,c.DistanceKm,c.EntryFee,c.MaximumParticipants)).ToList(),e.Routes.Select(r=>new RouteResponse(r.RouteId,r.EventId,r.RouteName,r.StartLocation,r.FinishLocation,r.RouteDistanceKm,r.RouteDescription)).ToList()));} [Authorize(Roles="Organiser"),HttpPost] public async Task<ActionResult<EventResponse>> Create(EventRequest r){var err=Validate(r);if(err!=null)return BadRequest(new{message=err});var e=new Event{OrganiserId=User.UserId(),EventName=r.EventName.Trim(),Description=r.Description,EventDate=r.EventDate,Venue=r.Venue.Trim(),City=r.City.Trim(),Province=r.Province.Trim(),EventType=r.EventType.Trim(),Status=r.Status.Trim()};db.Events.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(GetById),new{id=e.EventId},new EventResponse(e.EventId,e.OrganiserId,e.EventName,e.Description,e.EventDate,e.Venue,e.City,e.Province,e.EventType,e.Status,e.CreatedAt,e.BannerImageUrl));} [Authorize(Roles="Organiser"),HttpPut("{id:int}")] public async Task<ActionResult<EventResponse>> Update(int id,EventRequest r){var err=Validate(r);if(err!=null)return BadRequest(new{message=err});var e=await db.Events.FindAsync(id);if(e==null)return NotFound();if(e.OrganiserId!=User.UserId())return Forbid();e.EventName=r.EventName.Trim();e.Description=r.Description;e.EventDate=r.EventDate;e.Venue=r.Venue.Trim();e.City=r.City.Trim();e.Province=r.Province.Trim();e.EventType=r.EventType.Trim();e.Status=r.Status.Trim();await db.SaveChangesAsync();return Ok(new EventResponse(e.EventId,e.OrganiserId,e.EventName,e.Description,e.EventDate,e.Venue,e.City,e.Province,e.EventType,e.Status,e.CreatedAt,e.BannerImageUrl));} [Authorize(Roles="Organiser"),HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var e=await db.Events.FindAsync(id);if(e==null)return NotFound();if(e.OrganiserId!=User.UserId())return Forbid();db.Events.Remove(e);await db.SaveChangesAsync();return NoContent();} static string? Validate(EventRequest r){if(string.IsNullOrWhiteSpace(r.EventName)||string.IsNullOrWhiteSpace(r.Venue)||string.IsNullOrWhiteSpace(r.City)||string.IsNullOrWhiteSpace(r.Province))return "Event name, venue, city and province are required.";if(r.EventDate.Date<DateTime.UtcNow.Date)return "Event date cannot be in the past.";if(r.EventType is not("Running" or "Walking" or "Cycling"))return "Event type must be Running, Walking or Cycling.";if(r.Status is not("Upcoming" or "Draft" or "Completed" or "Cancelled"))return "Invalid event status.";return null;} }